attach(5);  // attaches the servo on pin 2 to the servo object\n  pinMode(fanPin, OUTPUT);\n\n}\n\nvoid loop() {\n  if (irrecv.decode(&results)) { //checking IR signal\n    if (results.value == 2155829415) {    // Power off/on\n      IO++;\n      if (IO % 2 == 0) {\n        fanState = HIGH;\n        digitalWrite(fanPin, fanState);\n        delay(100);\n      }\n      else {\n        fanState = LOW;\n        digitalWrite(fanPin, fanState);\n        delay(100);\n      }\n    }\n\n    if (results.value == 2155821255 ) {    // fan swing to left\n      for (pos; pos <= 89; pos += 1) { // goes from 0 degrees to 90 degrees\n        // in steps of 1 degree\n        myservo.write(pos);              // tell servo to go to position in variable 'pos'\n\n        delay(40);                       // waits 15ms for the servo to reach the position\n        if (irrecv.decode(&results)) {\n          irrecv.resume();\n          if (results.value == 2155870215)\n            break;\n        }\n      }\n    }\n\n    if (results.value == 2155870215 ) {    // fan swing to right\n      for (pos; pos >= 1; pos -= 1) { // goes from 90 degrees to 0 degrees\n        myservo.write(pos);              // tell servo to go to position in variable 'pos'\n        delay(40);                       // waits 15ms for the servo to reach the position\n\n        if (irrecv.decode(&results)) {\n          irrecv.resume();\n          if (results.value == 2155821255)\n            break;\n        }\n      }\n    }\n    Serial.println(pos);\n    Serial.println(results.value, HEX);\n    Serial.println(results.value);\n    irrecv.resume();                    //recive next intrustion\n  }\n  delay(100);\n}\n")),(0,t.yg)("h3",{id:"proyecto-2---coche-controlado-a-distancia"},"Proyecto 2 - Coche controlado a distancia"),(0,t.yg)("p",null,(0,t.yg)("strong",{parentName:"p"},"Visi\xf3n general")),(0,t.yg)("div",{align:"center"},(0,t.yg)("img",{width:400,src:"https://files.seeedstudio.com/wiki/Seeeduino-XIAO-Expansion-Board/